@namespace sv_825e5f14c4394ee4baaf68be1634e760.Components.Pages.Settings
@using sv_825e5f14c4394ee4baaf68be1634e760.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance Settings</h2>

    @if (_loading)
    {
        <p>Loading appearance settings...</p>
    }
    else
    {
        <!-- Theme Selector -->
        <div class="form-group">
            <label><strong>Theme</strong></label>
            <div class="radio-group">
                @foreach (var theme in _themes)
                {
                    <label class="radio-label">
                        <input type="radio" name="theme" value="@theme"
                               checked="@(_selectedTheme == theme)"
                               @onchange="() => _selectedTheme = theme" />
                        <span>@theme</span>
                    </label>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="form-group">
            <label><strong>Font Size</strong></label>
            <div class="radio-group">
                @foreach (var size in _fontSizes)
                {
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="@size"
                               checked="@(_selectedFontSize == size)"
                               @onchange="() => _selectedFontSize = size" />
                        <span>@size</span>
                    </label>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="form-group">
            <label for="language"><strong>Language</strong></label>
            <select id="language" @bind="_selectedLanguage" class="form-control">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode Toggle -->
        <div class="toggle-group">
            <label class="toggle-label">
                <input type="checkbox" @bind="_compactMode" class="toggle-switch" />
                <span>Compact Mode</span>
            </label>
        </div>

        <!-- Live Preview -->
        <div class="live-preview @GetPreviewClasses()">
            <h4>Preview</h4>
            <p>This is how your content will look with the selected settings.</p>
            <p><strong>Theme:</strong> @_selectedTheme | <strong>Font:</strong> @_selectedFontSize | <strong>Language:</strong> @_selectedLanguage</p>
            <p>@(_compactMode ? "Compact spacing is enabled." : "Standard spacing is enabled.")</p>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
        </div>

        @if (_successMessage is not null)
        {
            <div class="toast toast-success">@_successMessage</div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private string _selectedTheme = "System";
    private string _selectedFontSize = "Medium";
    private string _selectedLanguage = "English";
    private bool _compactMode;
    private string? _successMessage;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _selectedTheme = settings.Theme;
        _selectedFontSize = settings.FontSize;
        _selectedLanguage = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var theme = _selectedTheme.ToLowerInvariant();
        var font = _selectedFontSize.ToLowerInvariant();
        var compact = _compactMode ? "preview-compact" : "";
        return $"preview-{theme} preview-font-{font} {compact}";
    }

    private async Task SaveAsync()
    {
        var settings = new AppearanceSettings(_selectedTheme, _selectedFontSize, _selectedLanguage, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _successMessage = "Appearance saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _successMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

