+    color: #e0e0e0;
+    border-color: #555;
+}
+
+.preview-system {
+    background: #f9f9f9;
+    color: #333;
+}
+
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+.preview-compact {
